function genericPrint(path, options, print) {
  const n = path.getValue();
  const res = [];
  let index = n.start;

  path.each(childPath => {
    const child = childPath.getValue();
    res.push(options.originalText.slice(index, child.start));
    res.push(childPath.call(print));
